import { envBoolean, envPort, parseEnv } from '@lga/shared';
import { z } from 'zod';
import { parseActiveKeyring } from '../security/keyring.js';

export const APP_ENVS = ['local', 'test', 'staging', 'production'] as const;
export type AppEnv = (typeof APP_ENVS)[number];

const postgresUrl = z.url({
  protocol: /^postgres(ql)?$/,
  error: 'must be a postgresql:// connection URL',
});
const valkeyUrl = z.url({ protocol: /^rediss?$/, error: 'must be a redis:// or rediss:// URL' });
/** Server-side secret mixed into hashes. Generated by `pnpm setup`; never logged. */
const pepper = z.string().min(32, { error: 'must be at least 32 characters' }).max(256);

/** Variables shared by every backend process. */
const baseShape = {
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  APP_ENV: z.enum(APP_ENVS).default('local'),
  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace', 'silent']).default('info'),
  LOG_PRETTY: envBoolean.default(false),
  RELEASE: z.string().min(1).max(64).default('dev'),
  APP_ORIGIN: z.url(),
  DATABASE_URL: postgresUrl,
  DATABASE_POOL_MAX: z.coerce.number().int().min(1).max(50).default(10),
  VALKEY_URL: valkeyUrl,
  INTEGRATIONS_MODE: z.enum(['real', 'fake']).default('fake'),
  /** AES-256-GCM key ring for credential fields (ADR-0021): JSON `{"1":"<base64 32 bytes>"}`. */
  APP_ENCRYPTION_KEYS: z.string().min(2).max(8192),
  APP_ENCRYPTION_ACTIVE_VERSION: z.coerce.number().int().min(1).max(999_999),
  /** HMAC key ring for unsubscribe links (ADR-0024): JSON `{"1":"<base64 >= 32 bytes>"}`. */
  UNSUBSCRIBE_TOKEN_KEYS: z.string().min(2).max(8192),
  UNSUBSCRIBE_TOKEN_ACTIVE_KEY_ID: z.coerce.number().int().min(1).max(999_999),
  /** AI routing and pricing config files (ADR-0037); default: packages/core/config/*.yaml. */
  AI_ROUTING_FILE: z.string().min(1).optional(),
  AI_PRICING_FILE: z.string().min(1).optional(),
  /** Global AI kill switch (AIC-PRE-03): every AI call fails fast before reaching a provider. */
  AI_DISABLED: envBoolean.default(false),
  /** Provider keys. Required in real mode for every provider the routing config names. */
  ANTHROPIC_API_KEY: z.string().min(1).optional(),
  OPENAI_API_KEY: z.string().min(1).optional(),
};

export const baseServerEnvSchema = z.object(baseShape);
export type BaseServerEnv = z.output<typeof baseServerEnvSchema>;

/** Key rings must parse, hold valid keys and contain the active id. Messages never echo keys. */
function refineKeyrings(env: BaseServerEnv, ctx: z.RefinementCtx): void {
  const rings = [
    [
      'APP_ENCRYPTION_KEYS',
      env.APP_ENCRYPTION_KEYS,
      env.APP_ENCRYPTION_ACTIVE_VERSION,
      { exactBytes: 32 },
    ],
    [
      'UNSUBSCRIBE_TOKEN_KEYS',
      env.UNSUBSCRIBE_TOKEN_KEYS,
      env.UNSUBSCRIBE_TOKEN_ACTIVE_KEY_ID,
      { minBytes: 32 },
    ],
  ] as const;
  for (const [name, json, activeId, rules] of rings) {
    try {
      parseActiveKeyring(json, activeId, rules);
    } catch (error) {
      ctx.addIssue({ code: 'custom', path: [name], message: (error as Error).message });
    }
  }
}

function refineServerEnv(env: BaseServerEnv, ctx: z.RefinementCtx): void {
  refineKeyrings(env, ctx);
  if (env.APP_ENV !== 'production') return;
  if (env.INTEGRATIONS_MODE === 'fake') {
    ctx.addIssue({
      code: 'custom',
      path: ['INTEGRATIONS_MODE'],
      message: 'fake integrations are not allowed when APP_ENV=production',
    });
  }
  if (!env.APP_ORIGIN.startsWith('https://')) {
    ctx.addIssue({
      code: 'custom',
      path: ['APP_ORIGIN'],
      message: 'must use https:// when APP_ENV=production',
    });
  }
  if (env.LOG_PRETTY) {
    ctx.addIssue({
      code: 'custom',
      path: ['LOG_PRETTY'],
      message: 'pretty logs are not allowed when APP_ENV=production (logs must be JSON)',
    });
  }
}

export const apiEnvSchema = z
  .object({
    ...baseShape,
    API_PORT: envPort.default(4000),
    API_HOST: z.string().min(1).default('0.0.0.0'),
    /** Express `trust proxy` setting: only nginx on the private network is trusted. */
    TRUST_PROXY: z.string().min(1).default('loopback, linklocal, uniquelocal'),
    /** Session token hash pepper (ADR-0007). Rotating it signs everyone out. */
    SESSION_PEPPER: pepper,
    /** HMAC key for email-keyed rate limits and suppression hashes. */
    EMAIL_HASH_PEPPER: pepper,
    /** Cloudflare Turnstile server secret. Required with INTEGRATIONS_MODE=real. */
    TURNSTILE_SECRET_KEY: z.string().min(1).optional(),
    /**
     * Sign-in with Google / Microsoft (AUTH-03): OIDC client credentials. A provider is enabled in
     * real mode when both values are set; fake mode always enables a built-in fake provider.
     */
    GOOGLE_OAUTH_CLIENT_ID: z.string().min(1).optional(),
    GOOGLE_OAUTH_CLIENT_SECRET: z.string().min(1).optional(),
    MS_OAUTH_CLIENT_ID: z.string().min(1).optional(),
    MS_OAUTH_CLIENT_SECRET: z.string().min(1).optional(),
  })
  .superRefine((env, ctx) => {
    refineServerEnv(env, ctx);
    if (env.INTEGRATIONS_MODE === 'real' && !env.TURNSTILE_SECRET_KEY) {
      ctx.addIssue({
        code: 'custom',
        path: ['TURNSTILE_SECRET_KEY'],
        message: 'is required when INTEGRATIONS_MODE=real',
      });
    }
  });
export type ApiEnv = z.output<typeof apiEnvSchema>;

export const workerEnvSchema = z
  .object({
    ...baseShape,
    WORKER_HEALTH_PORT: envPort.default(4100),
    WORKER_HEALTH_HOST: z.string().min(1).default('0.0.0.0'),
    /** Multiplier for every queue's concurrency (lowered while the staging stack runs). */
    WORKER_CONCURRENCY_FACTOR: z.coerce.number().min(0.1).max(4).default(1),
    HEARTBEAT_INTERVAL_MS: z.coerce.number().int().min(1000).max(3_600_000).default(60_000),
    /**
     * System email relay: Mailpit locally (smtp://localhost:1125), the SES or Resend SMTP endpoint
     * in production (smtps://user:pass@host:465). Without it, emails go to the log-only fake mailer.
     */
    SMTP_URL: z
      .url({ protocol: /^smtps?$/, error: 'must be an smtp:// or smtps:// URL' })
      .optional(),
    MAIL_FROM: z.string().min(3).max(200).default('Lead Generation Agent <no-reply@localhost>'),
  })
  .superRefine((env, ctx) => {
    refineServerEnv(env, ctx);
    if (env.APP_ENV === 'production' && !env.SMTP_URL) {
      ctx.addIssue({
        code: 'custom',
        path: ['SMTP_URL'],
        message: 'is required when APP_ENV=production',
      });
    }
  });
export type WorkerEnv = z.output<typeof workerEnvSchema>;

export function loadApiEnv(source: Record<string, string | undefined> = process.env): ApiEnv {
  return parseEnv(apiEnvSchema, source, 'api');
}

export function loadWorkerEnv(source: Record<string, string | undefined> = process.env): WorkerEnv {
  return parseEnv(workerEnvSchema, source, 'worker');
}

/** Whether error details (e.g. failed health-check reasons) may be shown to clients. */
export function exposeErrorDetails(env: Pick<BaseServerEnv, 'APP_ENV'>): boolean {
  return env.APP_ENV !== 'production';
}
